	@Test
	public void retainsProjectionWhenChildHasInternalConstantVars() throws RDF4JException {
		String query = "SELECT ?s ?label WHERE { ?s <urn:label> ?label }";
		TupleExpr original = QueryParserUtil.parseQuery(QueryLanguage.SPARQL, query, null).getTupleExpr();
		Set<String> projectedNames = Set.of("s", "label");
		assertEquals(projectedNames, original.getBindingNames());

		TupleExpr optimized = original.clone();
		new ProjectionRemovalOptimizer().optimize(optimized, null, EmptyBindingSet.getInstance());

		assertAll(
				() -> assertTrue(((QueryRoot) optimized).getArg() instanceof Projection),
				() -> assertEquals(original.getBindingNames(), optimized.getBindingNames()));
	}

	@Test
	public void retainsProjectionForValuesAndExtensionOutputsNotMentionedAsVars() throws Exception {
		String query = "SELECT ?selected WHERE { "
				+ "VALUES (?selected ?valuesOnly) { (<urn:selected> <urn:valuesOnly>) } "
				+ "BIND(<urn:extensionOnly> AS ?extensionOnly) "
				+ "FILTER(?selected = <urn:selected>) }";
		TupleExpr parsed = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, query, null).getTupleExpr();
		TupleExpr original = new QueryRoot(parsed.clone());
		List<BindingSet> expected = evaluate(original);
		assertEquals(1, expected.size());
		assertEquals(Set.of("selected"), expected.getFirst().getBindingNames());

		TupleExpr optimized = new QueryRoot(parsed.clone());
		new ProjectionRemovalOptimizer().optimize(optimized, null, EmptyBindingSet.getInstance());
		List<BindingSet> actual = evaluate(optimized);

		assertEquals(1, actual.size());
		assertEquals(Set.of("selected"), actual.getFirst().getBindingNames());
	}

	private static List<BindingSet> evaluate(TupleExpr expression) throws Exception {
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(), null);
		List<BindingSet> results = new ArrayList<>();
		try (CloseableIteration<BindingSet> iteration = strategy.evaluate(expression, EmptyBindingSet.getInstance())) {
			while (iteration.hasNext()) {
				results.add(iteration.next());
			}
		}
		return results;
	}
